        self.sparks[#self.sparks + 1] = n
    end
    return true
end

-- veil: 0..1 darkness over the painting; tint: colour of the veil
function B:draw(veil, tint)
    local app = self.app
    local W, H = app.W, app.H
    local L = self.L
