    for _,b in ipairs(self.slots)do b.node:on(false);b.key=nil;b.job=nil;b.locomotionOrders=nil end
    self.flash.node:on(false);self.aura.node:on(false);self.animFx.node:on(false);self.animFxBack.node:on(false);self.animFxFront=nil
    if self.glow then self.glow:on(false) end
    if f.key=='nahida' then
        self.captureBmp=G.bitmap(self.layers.fx);self.captureBmp.node:on(false)
        for i=1,3 do self.assistants[i]=G.bitmap(self.layers.fx);self.assistants[i].node:on(false) end
    end
    local provider=Registry.provider(self.key)
    if provider and provider.newView then provider.newView(self,self.layers) end
