    {ck('COMMA'), 2, B.LP, 'ok2'}, {ck('PERIOD'), 2, B.HP, 'back2'}, {ck('SLASH'), 2, B.SK}, {ck('RSHIFT'), 2, B.BU},
    {ck('RCTRL'), 2, B.DA},
