function O.rosterWord(sa, sb, ca, cb) return (sa & 15) | ((sb & 15) << 4) | ((ca & 31) << 8) | ((cb & 31) << 13) end
function O.parseRoster(w)
    w = math.tointeger(w) or 0
    return {slots = {w & 15, (w >> 4) & 15}, chars = {(w >> 8) & 31, (w >> 13) & 31}}
