    end
    -- rows: gold label, white text, hairline
    local pg = PAGES[self.page]
    L:label(EN[self.page], W / 2 - 520, -H / 2 + 120, 1400, 220, 170, UI.WHITE, 'c', nil, 0.05 * pk)
    for i = 1, 8 do
