        local x = -W / 2 + 140 + (1 - a) * 60
        L:shape(G.RECT, x - 30, y, 10, 10, acc, a, 45)
        L:label(ln and ln[1] or '', x + 120, y, 240, 60, 26, acc, 'l', nil, a)
