    local out = {}
    for i = 1, #src do
        local e = src[i]
        local c = {}
        for k, v in pairs(e) do c[k] = v end
        out[i] = c
    end
    return out
end

local function copyFighter(p)
    local c = {}
    for k, v in pairs(p) do c[k] = v end
    local h = {}
    for k = 0, HIST - 1 do h[k] = p.hist[k] end
    c.hist = h
    c.dots = copyList(p.dots)
    local st = {}
    for k, v in pairs(p.stats) do st[k] = v end
    c.stats = st
    return c
end

