    am = am or 1
    if el == 'pyro' then
        L:shape(G.TRI, x, y + s * 0.16, s * 0.5, s * 0.72, col, am)
        L:shape(G.ELLIPSE, x, y - s * 0.14, s * 0.56, s * 0.56, col, am)
