        L:shape(G.ELLIPSE, x - s * 0.1, y - s * 0.06, s * 0.16, s * 0.24, core, 0.85 * am, 20)
    elseif el == 'anemo' then
        local bg = UI.NAVY
        L:shape(G.ELLIPSE, x, y, s * 0.8, s * 0.8, col, am)
