   if t==70 or t==94 or t==118 then
    self:hit(p,d,{damage=t==118 and 96 or 97,hitstun=160,blockstun=18,push=0,energy=0,level='mid',shake=9},'burst',{unblockable=true,ignoreInvul=true})
    p.hitstop,d.hitstop=0,0 -- delivered cinematic has one continuous clock
   end
   local root=D.burstRoots[math.min(163,t+1)]
   d.x=p.x+p.face*root[1];d.y=root[2];d.vx,d.vy=0,0
   if t>=162 then self:setState(d,'down');d.y=0;self:setState(p,'idle') end
  elseif t>=24 then self:setState(p,p.y>0 and 'air' or 'idle') end
 end
 local function throwTick(self,p)
  local t,d=p.t,p.foe;p.vx=0
  local root=D.throwRoots[math.min(51,t+1)]
  if t<42 then d.x=p.x+p.face*root[1];d.y=root[2];d.vx,d.vy=0,0;d.face=-p.face;d.t=t end
  if t==32 then
   local dmg=K.throw.damage;d.hp=math.max(0,d.hp-dmg);p.energy=math.min(100,p.energy+K.throw.energy)
   p.stats.damage=p.stats.damage+dmg;d.combo,d.comboDmg=1,dmg
   if d.hp<=0 then d.ko=true;self:emit({type='ko',p=d.id,by=p.id,x=d.x,y=d.y+170*C}) end
   self:emit({type='hit',p=d.id,by=p.id,kind='throw',dmg=dmg,combo=1,x=d.x,y=d.y+170*C,element=p.element,heavy=true,shake=9,weapon=p.weapon})
  end
  if t==42 then self:setState(d,'down');d.y=0;self:emit({type='land',p=d.id,x=d.x,hard=true}) end
  if t>=50 then self:setState(p,'idle') end
 end
 function S:fighterTick(p)
  if locked(p) then return end
  if p.key=='arlecchino' and p.state=='throw' then p.t=p.t+1;throwTick(self,p);return end
  oldFighter(self,p)
 end
 function S:physics(p)
  if locked(p) then return end
  return oldPhysics(self,p)
 end
end
end
__loaders['gf_sim_team']=function()
-- Three stocks per side. Rendering readiness never changes simulation timing.
return function(S,newFighter,C)
 local oldNew,oldFlow=S.new,S.flow
 function S.new(opts)
  if not opts.teams then return oldNew(opts) end
  local copy={};for k,v in pairs(opts)do copy[k]=v end
  for side=1,2 do assert(#opts.teams[side]==3,'team requires three fighters');local seen={}
   for _,char in ipairs(opts.teams[side])do assert(char.key and not seen[char.key],'invalid or repeated team fighter');seen[char.key]=true end
  end
  copy.chars={opts.teams[1][1],opts.teams[2][1]};copy.rounds=1;copy.training=false
  local self=oldNew(copy);self.teams=opts.teams;self.teamIndex={1,1};self.teamBout=1
  return self
 end
 function S:flow()
  if not self.teams or self.phase~='ko' or self.phaseT<90 then return oldFlow(self) end
  local winner=self.roundWinner;local advance={winner~=1 or self.f[1].hp<=0,winner~=2 or self.f[2].hp<=0}
  local exhausted={false,false}
  for side=1,2 do if advance[side] then
   self.teamIndex[side]=self.teamIndex[side]+1;exhausted[side]=self.teamIndex[side]>3
  end end
  if exhausted[1] or exhausted[2] then
   self.phase='over';self.phaseT=0
   if exhausted[1] and exhausted[2] then self.matchWinner=nil else self.matchWinner=exhausted[1] and 2 or 1 end
   self:emit({type='matchEnd',winner=self.matchWinner,team=true});return
  end
  local hp,energy={},{}
  for side=1,2 do
   hp[side],energy[side]=self.f[side].hp,self.f[side].energy
   if advance[side] then
    self.f[side]=newFighter(side,self.teams[side][self.teamIndex[side]],(side==1 and -260 or 260)*C,side==1 and 1 or -1)
    hp[side],energy[side]=self.f[side].maxhp,0
   end
  end
  self.f[1].foe,self.f[2].foe=self.f[2],self.f[1]
  self.teamBout=self.teamBout+1;self.round=self.teamBout
  self:startRound(false)
  for side=1,2 do self.f[side].hp=hp[side];self.f[side].energy=energy[side] end
  self:emit({type='teamSwap',index1=self.teamIndex[1],index2=self.teamIndex[2],bout=self.teamBout})
 end
end
end
local POOLS = {img = 256, txt = 96, btn = 24}
GF_POOLS = POOLS

local root, host
local started, failed = false, false
local boot = {stage = 'collect', i = 1}
local imgs, txts, btns = {}, {}, {}
local G, App, app
local errors = 0
local stageName = 'load'

local function safe(f, ...)
    local ok, a, b = pcall(f, ...)
    if not ok then
        errors = errors + 1
        if errors <= 30 then printerr('GF error', tostring(a)) end
        return nil
    end
    return a, b
end

local function showError(message)
    failed = true
    message = '[' .. stageName .. '] ' .. tostring(message)
    printerr('GF fatal ' .. message)
    local t = host
    if not t then return end
    pcall(function()
        t:SetVisible(true)
        t:SetActive(true)
        local cw,ch=game.GetUICanvasSize()
        if type(cw)~='number' or type(ch)~='number' or cw<=0 or ch<=0 then cw,ch=1600,900 end
        root:SetAnchorMin(0,0);root:SetAnchorMax(1,1);root:SetPivot(.5,.5)
        root:SetSizeDelta(0,0);root:SetAnchoredPosition(0,0);root:SetLocalScale(1,1,1)
        t:SetAnchorMin(0,0);t:SetAnchorMax(1,1);t:SetPivot(.5,.5)
        t:SetSizeDelta(math.max(240,cw*.12),math.max(160,ch*.08));t:SetAnchoredPosition(0,0);t:SetLocalScale(1,1,1)
        t.fontSize = 22; t.fontColor = Color(255, 255, 255, 255); t.bgColor = Color(150, 20, 30, 235)
        t.text = '原神格斗 出错了（请截图反馈）\n' .. message
        t:SetAsLastSibling()
    end)
end

local clock = 0

local function start()
    if started then return end
    host = script.object
    if not host then printerr('GF no host') return end
    started = true
    root = host.parent or host
    local ok, err = pcall(script.EnableUpdate, script, true)
    if not ok then showError('无法启用逐帧更新：' .. tostring(err)); return end
    pcall(function() host.text = 'GF LUA 已初始化 / 等待逐帧更新' end)
end

function OnInit() start() end
function OnEnable() start() end
function OnStart() start() end

function GF_APP() return app end

local function collect()
    local kids = root:GetChildren()
    boot.kids = kids
    boot.i = 1
    boot.stage = 'names'
end

local function names(budget)
    local kids = boot.kids
    local stop = math.min(#kids, boot.i + budget - 1)
    for k = boot.i, stop do
        local c = kids[k]
        local name = c.name
        if type(name) == 'string' then
            local n = tonumber(name:match('^GF_IMG_(%d+)$'))
            if n then imgs[n] = c
            else
                n = tonumber(name:match('^GF_TXT_(%d+)$'))
                if n then txts[n] = c
                else
                    n = tonumber(name:match('^GF_BTN_(%d+)$'))
                    if n then btns[n] = c end
                end
            end
        end
    end
    boot.i = stop + 1
    return stop >= #kids
end

local function dense(t)
    local out = {}
    local i = 1
    while t[i] do out[i] = t[i]; i = i + 1 end
    return out
end

local BOOT_STEPS = {
    collect = function() collect() end,
    names = function()
        if names(3000) then boot.stage = 'pools' end
    end,
    pools = function()
        G = require('gf_gfx')
        imgs, txts, btns = dense(imgs), dense(txts), dense(btns)
        if #imgs < 256 or #txts < 96 then
            error(('控件池缺失：图片 %d / %d，文字 %d / %d（检查 GIA 是否完整导入）'):format(#imgs, POOLS.img, #txts, POOLS.txt))
        end
        G.init({game = game, Enum = Enum, Color = Color, safe = safe},
               {root = root, imgs = imgs, txts = txts, btns = btns})
        -- Actual image template resource index supplied for this editor project.
        local okIndex,templateIndex=pcall(script.GetParam,script,'GF_IMAGE_TEMPLATE_INDEX')
        templateIndex=okIndex and tonumber(templateIndex) or nil
        G.configureSecondPool(templateIndex or GF_DYNAMIC_IMAGE_TEMPLATE_INDEX or 1073741845)
        -- Imported fixed-size containers must follow the actual canvas on wide phones.
        safe(function()
            root:SetAnchorMin(0, 0); root:SetAnchorMax(1, 1)
            root:SetPivot(0.5, 0.5); root:SetSizeDelta(0, 0)
            root:SetAnchoredPosition(0, 0)
        end)
        safe(host.SetVisible, host, false)
        pcall(function() root.disableKeyEventPassthrough = true end)
        G.parkAll()
        boot.stage = 'park'
    end,
    park = function()
        if G.flush(1800) <= 0 then boot.stage = 'app' end
    end,
    app = function()
        App = require('gf_app')
        app = App.new({game = game, Enum = Enum, Color = Color, safe = safe, host = host, root = root,
                       script = script, pools = POOLS, firstScene = GF_FIRST_SCENE, firstArgs = GF_FIRST_ARGS, settings = GF_SETTINGS,teamBattleIO=GF_TEAM_NETIO,
                       netio = GF_NETIO or require('gf_transport').new(game, script, function() return clock end)})
        boot.stage = 'run'
    end,
}

function OnUpdate(dt)
    if failed or not started then return end
    clock = clock + (dt or 0)
    if boot.stage ~= 'run' then
        stageName = 'boot:' .. boot.stage
        pcall(function() host.text = 'GF 启动阶段：' .. boot.stage end)
        local ok, err = pcall(BOOT_STEPS[boot.stage])
        if not ok then showError(err) end
        return
    end
    stageName = 'run'
    local ok, err = pcall(app.update, app, dt)
    if not ok then
        app.fatal = (app.fatal or 0) + 1
        printerr('GF update error ' .. tostring(err))
        -- A failed allocation/draw can leave a partially completed job. Never
        -- repeat it for twenty updates and allocate more controls on each retry.
        showError(err)
    end
end

function GF_SECOND_POOL_STATUS() return G and G.secondPoolStatus() end


function GF_PERF_STATUS() return app and app.perf end
